 * epilogue drains buffer ((j-1)&1); the wait moves two items back. */
constexpr int NACC = PP ? 2 : 1;
constexpr int TCOLS = NACC * ACC + SFS * SFC * (NSFB_E + 1);
/* J3: allocate the smallest power of two that holds TCOLS instead of
 * rounding everything to 256. This is inert for every rung that existed
 * before it -- GEMM1 BN=64 has TCOLS = 128 + 48*SFS >= 176, GEMM2 BN=128 has
 * 128 + 32*SFS >= 160, and the BN=64 ping-pong form has 2*64 + 64 = 192 --
 * and it exists because BN=64 GEMM2 *without* ping-pong has
 * TCOLS = 64 + 32*SFS = 128 at SFS=2. TMEM is 512 columns per SM shared by
 * the resident CTAs, so a 256-column allocation caps occupancy at two CTAs
 * no matter what smem and registers allow; a 128-column one does not. NCU on
 * these bytes (dv_f48b9d918f2d) puts both WS3 GEMMs at 20.8-21.2% of peak
 * warps against a `maximum_warps_per_active_cycle_pct` of 21.88, i.e. exactly
 * at that two-CTA ceiling, with no unit above 50%. */
constexpr int TALLOC = TCOLS <= 128 ? 128 : (TCOLS <= 256 ? 256 : 512);

if constexpr (V0_X16) {
  // X10: x16-rotated pair drain (wide wd1 pattern generalized to the
  // 2-kb pair): the next 32-col batch's loads issue before the
  // current batch's FFMA so tmem-port reads overlap ALU (wait::ld is
  // all-outstanding -> issue,fma,wait order). Two buffer pairs
  // (v0*,v1*) alternate; fully unrolled so ptxas renames without
  // copies. pe arrive after the LAST load retires, before the final
  // FFMA batch (same relative point as wide wd1). Per-element FFMA
  // order (kb0 then kb1, increasing col) matches the x32-batched
  // code exactly -> bitwise-identical outputs.

tmem_ld_x16(ta1 + 3 * 32 + 0, v1a);
tmem_ld_x16(ta1 + 3 * 32 + 16, v1b);
#pragma unroll
for (int i = 0; i < 16; ++i) fin[2 * 32 + i] = fmaf(sc1, __uint_as_float(v0a[i]), fin[2 * 32 + i]);
#pragma unroll
for (int i = 0; i < 16; ++i) fin[2 * 32 + 16 + i] = fmaf(sc1, __uint_as_float(v0b[i]), fin[2 * 32 + 16 + i]);
tmem_ld_wait();               // all tmem reads of this slot done
bar_arrive(su32(pe_bar + pb));
#pragma unroll
for (int i = 0; i < 16; ++i) fin[3 * 32 + i] = fmaf(sc1, __uint_as_float(v1a[i]), fin[3 * 32 + i]);
#pragma unroll
for (int i = 0; i < 16; ++i) fin[3 * 32 + 16 + i] = fmaf(sc1, __uint_as_float(v1b[i]), fin[3 * 32 + 16 + i]);

  constexpr int PROLOG_CH = D / 16;
  constexpr int PROLOG_QITER = (BM * PROLOG_CH) / THR;
  uint32_t sfw[DCH];
  uint4 qd[PROLOG_QITER];
#if !FMHA_PROBE_LEVEL
  if (warp < 4) {
#pragma unroll
    for (int g = 0; g < DCH; ++g) {
      const uint8_t* slice = p.sfq + (int64_t)(b * p.H + h) * p.Rpq * p.Cq;
      sfw[g] = valid ? ldg32(slice + sf_rowwise_offset(iClamped, 4 * g, p.Cq)) : 0x7f7f7f7fu;
    }
  }
#pragma unroll
  for (int it = 0; it < PROLOG_QITER; ++it) {
    const int c = it * THR + tid;
    const int r = c / PROLOG_CH;
    const int iq = PAD_SKIP ? (q0 + (r >> log2G)) : (q0 + (r & (Qph - 1)));
    qd[it] = make_uint4(0u, 0u, 0u, 0u);
    if (iq < p.Sq) {
      const int ci = c - r * PROLOG_CH;
      const int hq = PAD_SKIP ? (kh * G + (r & (G - 1))) : (kh * G + (r >> log2Qph));
      qd[it] = ldg128(p.q + b * p.q_b + (int64_t)hq * p.q_h + (int64_t)iq * p.q_s + ci * 16);

if (tid < 32) tcg_alloc(&tmem_base_s, TT::ALLOC);
__syncthreads();
const uint32_t tmem = tmem_base_s;
const uint32_t tlane = tmem + ((uint32_t)((warp & 3) * 32) << 16);
if (tid < 32) tcg_relinquish();

